const arr = [1, 2];
// arr.map((x) => [x, x * 10])：會變成 [[1, 10], [2, 20]]，是巢狀陣列
// arr.flatMap((x) => [x, x * 10])：會變成 [1, 10, 2, 20]，是攤平後的陣列

const arr = [1, 2];

const withMap = arr.map((x) => [x, x * 10]);
const withFlatMap = arr.flatMap((x) => [x, x * 10]);

console.log(withMap);
console.log(withFlatMap);

